function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // 29x29 grid representing 841 (29^2)
  for (let i = 0; i < 29; i++) {
    for (let j = 0; j < 29; j++) {
      ctx.beginPath();
      ctx.rect(i * (W / 29) + Math.sin(t + i) * 2, j * (H / 29) + Math.cos(t + j) * 2, W / 29, H / 29);
      ctx.stroke();
    }
  }
  ctx.restore();
}
